def transform(grid):
    h=len(grid); w=len(grid[0])
    colors=set(x for r in grid for x in r)
    def dominant(c):
        return sum(1 for r in grid if sum(x==c for x in r)==max(sum(x==z for x in r) for z in colors))
    def total(c): return sum(x==c for r in grid for x in r)
    m=min(colors,key=lambda c:(dominant(c),total(c)))
    def bg(r):
        cs=[c for c in colors if c!=m]
        return max(cs,key=lambda c:r.count(c))
    out=[row[:] for row in grid]
    for a in range(0,h,2):
        b=min(a+2,h); marks=set()
        for i in range(a,b):
            for j in range(w):
                if grid[i][j]==m: marks.add(j)
        for i in range(a,b):
            q=bg(grid[i])
            for j in range(w): out[i][j]=m if j in marks else q
    return out

